# Atlas cache lab: temporal locality
# Generated by gen_bench.py (E8). Deterministic, no input; ends by running off the end.
# A 64-word (256-byte) array swept 4 times at stride 1: reuse after the first sweep.
# 'addi x0, x0, 0' lines are padding: the nh-nf pipeline has no hazard unit, so every
# register write is followed by 2 nops and all five models compute the same addresses.
    lui x5, 0x10             # x5 = array base 0x10000
    addi x0, x0, 0
    addi x0, x0, 0
    addi x7, x5, 256         # x7 = end = base + 256
    addi x0, x0, 0
    addi x0, x0, 0
    addi x10, x0, 4           # x10 = sweeps left
    addi x0, x0, 0
    addi x0, x0, 0
outer:
    addi x6, x5, 0           # x6 = pointer
    addi x0, x0, 0
    addi x0, x0, 0
loop:
    lw x9, 0(x6)             # the measured access
    addi x0, x0, 0
    addi x0, x0, 0
    add x8, x8, x6           # x8 = checksum of the addresses read
    addi x0, x0, 0
    addi x0, x0, 0
    addi x6, x6, 4          # stride 1 word(s)
    addi x0, x0, 0
    addi x0, x0, 0
    blt x6, x7, loop
    addi x10, x10, -1
    addi x0, x0, 0
    addi x0, x0, 0
    bne x10, x0, outer
